import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        t = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(t):
        n = int(next(iterator))
        s = next(iterator)

        chars = set(s)
        min_ops = float('inf')
        found = False

        for char_to_remove in chars:
            left = 0
            right = n - 1
            ops = 0
            possible = True

            while left < right:
                if s[left] == s[right]:
                    left += 1
                    right -= 1
                elif s[left] == char_to_remove:
                    left += 1
                    ops += 1
                elif s[right] == char_to_remove:
                    right -= 1
                    ops += 1
                else:
                    possible = False
                    break

            if possible:
                found = True
                if ops < min_ops:
                    min_ops = ops

        if found:
            results.append(str(min_ops))
        else:
            results.append("-1")

    print('\n'.join(results))

if __name__ == "__main__":
    solve()
